// DecodeGetUserContextRequest returns a decoder for requests sent to the user
// get_user_context endpoint.
func DecodeGetUserContextRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (any, error) {
	return func(r *http.Request) (any, error) {
		var (
			id                    string
			includeDerived        bool
			includeSession        bool
			includeAccessPatterns bool
			err                   error

			params = mux.Vars(r)
		)
		id = params["id"]
		err = goa.MergeErrors(err, goa.ValidateFormat("id", id, goa.FormatUUID))
		qp := r.URL.Query()
		{
			includeDerivedRaw := qp.Get("include_derived")
			if includeDerivedRaw == "" {
				includeDerived = true
			} else {
				v, err2 := strconv.ParseBool(includeDerivedRaw)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("include_derived", includeDerivedRaw, "boolean"))
				}
				includeDerived = v
			}
		}
		{
			includeSessionRaw := qp.Get("include_session")
			if includeSessionRaw == "" {
				includeSession = true
			} else {
				v, err2 := strconv.ParseBool(includeSessionRaw)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("include_session", includeSessionRaw, "boolean"))
				}
				includeSession = v
			}
		}
		{
			includeAccessPatternsRaw := qp.Get("include_access_patterns")
			if includeAccessPatternsRaw != "" {
				v, err2 := strconv.ParseBool(includeAccessPatternsRaw)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("include_access_patterns", includeAccessPatternsRaw, "boolean"))
				}
				includeAccessPatterns = v
			}
		}
		if err != nil {
			return nil, err
		}
		payload := NewGetUserContextPayload(id, includeDerived, includeSession, includeAccessPatterns)

		return payload, nil
	}
}

