// DecodeListRequest returns a decoder for requests sent to the user list
// endpoint.
func DecodeListRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (any, error) {
	return func(r *http.Request) (any, error) {
		var (
			page           uint
			pageSize       uint
			sortBy         *string
			sortOrder      string
			emailFilter    *string
			statusFilter   *string
			userTypeFilter *string
			err            error
		)
		qp := r.URL.Query()
		{
			pageRaw := qp.Get("page")
			if pageRaw == "" {
				page = 1
			} else {
				v, err2 := strconv.ParseUint(pageRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("page", pageRaw, "unsigned integer"))
				}
				page = uint(v)
			}
		}
		if page < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("page", page, 1, true))
		}
		{
			pageSizeRaw := qp.Get("page_size")
			if pageSizeRaw == "" {
				pageSize = 20
			} else {
				v, err2 := strconv.ParseUint(pageSizeRaw, 10, strconv.IntSize)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("page_size", pageSizeRaw, "unsigned integer"))
				}
				pageSize = uint(v)
			}
		}
		if pageSize < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("page_size", pageSize, 1, true))
		}
		if pageSize > 100 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("page_size", pageSize, 100, false))
		}
		sortByRaw := qp.Get("sort_by")
		if sortByRaw != "" {
			sortBy = &sortByRaw
		}
		sortOrderRaw := qp.Get("sort_order")
		if sortOrderRaw != "" {
			sortOrder = sortOrderRaw
		} else {
			sortOrder = "desc"
		}
		if !(sortOrder == "asc" || sortOrder == "desc") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("sort_order", sortOrder, []any{"asc", "desc"}))
		}
		emailFilterRaw := qp.Get("email_filter")
		if emailFilterRaw != "" {
			emailFilter = &emailFilterRaw
		}
		statusFilterRaw := qp.Get("status_filter")
		if statusFilterRaw != "" {
			statusFilter = &statusFilterRaw
		}
		if statusFilter != nil {
			if !(*statusFilter == "ACTIVE" || *statusFilter == "INACTIVE" || *statusFilter == "LOCKED" || *statusFilter == "SUSPENDED" || *statusFilter == "PENDING_VERIFICATION" || *statusFilter == "EXPIRED") {
				err = goa.MergeErrors(err, goa.InvalidEnumValueError("status_filter", *statusFilter, []any{"ACTIVE", "INACTIVE", "LOCKED", "SUSPENDED", "PENDING_VERIFICATION", "EXPIRED"}))
			}
		}
		userTypeFilterRaw := qp.Get("user_type_filter")
		if userTypeFilterRaw != "" {
			userTypeFilter = &userTypeFilterRaw
		}
		if userTypeFilter != nil {
			if !(*userTypeFilter == "INTERNAL" || *userTypeFilter == "CUSTOMER" || *userTypeFilter == "VENDOR" || *userTypeFilter == "PARTNER" || *userTypeFilter == "API" || *userTypeFilter == "SERVICE" || *userTypeFilter == "ADMIN") {
				err = goa.MergeErrors(err, goa.InvalidEnumValueError("user_type_filter", *userTypeFilter, []any{"INTERNAL", "CUSTOMER", "VENDOR", "PARTNER", "API", "SERVICE", "ADMIN"}))
			}
		}
		if err != nil {
			return nil, err
		}
		payload := NewListPayload(page, pageSize, sortBy, sortOrder, emailFilter, statusFilter, userTypeFilter)

		return payload, nil
	}
}

